function T(r){for(;r>Math.PI;)r-=2*Math.PI;for(;r<-Math.PI;)r+=2*Math.PI;return r}function I(r,n,l,t,e){let m=e*2.4,s=m*.2,a=m*.6*.5,M=45*Math.PI/180,h=n-Math.cos(t)*s,c=l-Math.sin(t)*s,g=r.trailerX-Math.cos(r.trailerAngle)*a,b=r.trailerY-Math.sin(r.trailerAngle)*a,i=r.trailerAngle,o=h-g,u=c-b;if(o*o+u*u>.25){let Y=Math.atan2(u,o),A=T(Y-t),d=Math.max(-M,Math.min(M,A));i=t+d}let X=h-Math.cos(i)*a,x=c-Math.sin(i)*a;return{headX:n,headY:l,headAngle:t,hitchX:h,hitchY:c,trailerAngle:i,trailerX:X,trailerY:x}}function L(r,n){let e=n*2.4*.6*.5;return[{x:r.headX,y:r.headY},{x:r.trailerX,y:r.trailerY},{x:r.trailerX+Math.cos(r.trailerAngle)*e,y:r.trailerY+Math.sin(r.trailerAngle)*e},{x:r.trailerX-Math.cos(r.trailerAngle)*e,y:r.trailerY-Math.sin(r.trailerAngle)*e}]}export{I as a,L as b};
